from openpyxl import load_workbook
for fn in ['inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_179-P1.xlsx','inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_SRR5456220.xlsx','inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_380-P.xlsx']:
    wb=load_workbook(fn, read_only=False, data_only=True)
    print('\\n',fn)
    for ws in wb.worksheets:
        print(ws.title, 'calc_dim',ws.calculate_dimension(),'max',ws.max_row,ws.max_column)
        for i,row in enumerate(ws.iter_rows(min_row=1,max_row=5,values_only=True),1):
            print(i,list(row)[:33])
PY"

