python - "$(inputs.chip_genes.path)" "$(inputs.trio_status.path)" "$(inputs.variants.path)" <<'PY'
import csv
import math
import re
import sys
import zipfile
import xml.etree.ElementTree as ET
from pathlib import Path

def local_name(tag):
    return tag.rsplit("}", 1)[-1]

def cell_column(ref):
    letters = []
    for ch in ref:
        if ch.isalpha():
            letters.append(ch.upper())
        else:
            break
    n = 0
    for ch in letters:
        n = n * 26 + ord(ch) - 64
    return n - 1

def read_xlsx(path):
    with zipfile.ZipFile(str(path), "r") as zf:
        names = set(zf.namelist())
        shared = []
        if "xl/sharedStrings.xml" in names:
            root = ET.fromstring(zf.read("xl/sharedStrings.xml"))
            for si in root.iter():
                if local_name(si.tag) == "si":
                    parts = []
                    for node in si.iter():
                        if local_name(node.tag) == "t" and node.text is not None:
                            parts.append(node.text)
                    shared.append("".join(parts))
        sheet_names = sorted(
            n for n in names
            if n.startswith("xl/worksheets/sheet") and n.endswith(".xml")
        )
        if not sheet_names:
            raise RuntimeError("No worksheet XML found in " + str(path))
        root = ET.fromstring(zf.read(sheet_names[0]))
        rows = []
        for row_node in root.iter():
            if local_name(row_node.tag) != "row":
                continue
            vals = {}
            for cell in row_node:
                if local_name(cell.tag) != "c":
                    continue
                ref = cell.attrib.get("r", "")
                if not ref:
                    continue
                idx = cell_column(ref)
                cell_type = cell.attrib.get("t", "")
                value_node = None
                for child in cell:
                    if local_name(child.tag) == "v":
                        value_node = child
                        break
                if cell_type == "inlineStr":
                    parts = []
                    for child in cell.iter():
                        if local_name(child.tag) == "t" and child.text is not None:
                            parts.append(child.text)
                    value = "".join(parts)
                elif value_node is None or value_node.text is None:
                    value = ""
                else:
                    raw = value_node.text
                    if cell_type == "s":
                        value = shared[int(raw)]
                    elif cell_type == "b":
                        value = "TRUE" if raw == "1" else "FALSE"
                    else:
                        value = raw
                vals[idx] = value
            if vals:
                width = max(vals) + 1
                row_values = [""] * width
                for idx, value in vals.items():
                    row_values[idx] = value
                rows.append(row_values)
        return rows

def text(value):
    if value is None:
        return ""
    return str(value).strip()

def norm_id(value):
    s = text(value)
    if re.fullmatch(r"[0-9]+[.]0", s):
        s = s[:-2]
    return s

def header_map(row):
    return {text(v): i for i, v in enumerate(row) if text(v)}

def col_index(headers, label):
    if label not in headers:
        raise RuntimeError("Missing required column: " + label)
    return headers[label]

def parse_float(value):
    s = text(value).replace(",", "")
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None

def carrier_sample_id(rows, path):
    if rows:
        for value in rows[0]:
            s = text(value)
            if re.search(r"(?:Proband|Mother|Father|Child)[^()]*\(([^)]+)\)", s):
                token = re.search(r"\(([^)]+)\)", s).group(1)
                return norm_id(token.split("-", 1)[0])
    m = re.search(r"CHIP_([^./]+)", path.name)
    if m:
        return norm_id(m.group(1).split("-", 1)[0])
    raise RuntimeError("Could not determine sample ID for " + str(path))

def variant_paths(spec):
    p = Path(spec)
    if p.is_dir():
        paths = sorted(
            q for q in p.rglob("*")
            if q.is_file() and zipfile.is_zipfile(str(q))
        )
    elif p.is_file() and zipfile.is_zipfile(str(p)):
        paths = [p]
    else:
        paths = []
    if not paths:
        raise RuntimeError("No XLSX files were exposed for the variant collection: " + str(p))
    return paths

chip_path = Path(sys.argv[1])
status_path = Path(sys.argv[2])
variants_spec = sys.argv[3]

chip_rows = read_xlsx(chip_path)
chip_genes = set()
for row in chip_rows:
    if row and text(row[0]):
        chip_genes.add(text(row[0]).upper())
if not chip_genes:
    raise RuntimeError("The supplied CHIP gene workbook was empty")

status_rows = read_xlsx(status_path)
if not status_rows:
    raise RuntimeError("The supplied trio-status workbook was empty")
status_headers = header_map(status_rows[0])
sid_col = col_index(status_headers, "Sample ID")
blm_col = col_index(status_headers, "BLM Mutation Status")
carrier_ids = set()
for row in status_rows[1:]:
    if len(row) <= max(sid_col, blm_col):
        continue
    sid = norm_id(row[sid_col])
    blm = text(row[blm_col])
    if sid and blm == "Carrier":
        carrier_ids.add(sid)
if not carrier_ids:
    raise RuntimeError("No Carrier samples were found in the supplied trio-status workbook")

denominator = 0
numerator = 0
seen_carrier_ids = set()
files_by_carrier = {}
for path in variant_paths(variants_spec):
    rows = read_xlsx(path)
    sid = carrier_sample_id(rows, path)
    if sid not in carrier_ids:
        continue
    seen_carrier_ids.add(sid)
    files_by_carrier.setdefault(sid, []).append(path.name)
    header_row = None
    for row_number, row in enumerate(rows):
        h = header_map(row)
        if "Chr:Pos" in h and "Variant Allele Freq" in h:
            header_row = row_number
            headers = h
            break
    if header_row is None:
        raise RuntimeError("Required variant header not found in " + path.name)
    gene_col = col_index(headers, "Gene Names")
    seq_col = col_index(headers, "Sequence Ontology (Combined)")
    vaf_col = col_index(headers, "Variant Allele Freq")
    zyg_col = col_index(headers, "Zygosity")
    clinvar_col = col_index(headers, "Classification")
    for row in rows[header_row + 1:]:
        width = max(gene_col, seq_col, vaf_col, zyg_col, clinvar_col)
        if len(row) <= width:
            row = row + [""] * (width + 1 - len(row))
        vaf = parse_float(row[vaf_col])
        if vaf is None or not vaf < 0.3:
            continue
        if text(row[zyg_col]).casefold() == "reference":
            continue
        seq = text(row[seq_col])
        if re.search(r"intron|intergenic|utr", seq, flags=re.IGNORECASE):
            continue
        gene_tokens = re.findall(r"[A-Za-z0-9][A-Za-z0-9_.-]*", text(row[gene_col]).upper())
        if not any(gene in chip_genes for gene in gene_tokens):
            continue
        classification = text(row[clinvar_col])
        if not classification:
            continue
        denominator += 1
        if classification.casefold() in {"benign", "likely benign"}:
            numerator += 1

missing_carrier_ids = sorted(carrier_ids - seen_carrier_ids)
proportion = (float(numerator) / float(denominator)) if denominator else float("nan")
with open("summary.tsv", "w", newline="") as handle:
    writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
    writer.writerow(["metric", "value"])
    writer.writerow(["carrier_sample_count", len(carrier_ids)])
    writer.writerow(["carrier_workbooks_with_data", len(seen_carrier_ids)])
    writer.writerow(["carrier_samples_without_variant_workbook", ",".join(missing_carrier_ids)])
    writer.writerow(["carrier_sample_ids", ",".join(sorted(carrier_ids))])
    writer.writerow(["chip_gene_count", len(chip_genes)])
    writer.writerow(["somatic_chip_variants_with_clinvar_classification", denominator])
    writer.writerow(["benign_or_likely_benign_variants", numerator])
    writer.writerow(["proportion_benign_or_likely_benign", "nan" if math.isnan(proportion) else format(proportion, ".15g")])
    writer.writerow(["filters", "VAF<0.3; supplied CHIP gene list; exclude intronic/intergenic/UTR sequence ontology; exclude Reference zygosity; non-empty ClinVar Classification"])

